  1	\chapter{Self-improvement}
  2	\label{chap:self-improvement}
  3	
  4	Throughout this chapter, $(\psi,A,B,L)$ is an $(\eps,\delta,\gamma)$-good symmetric strategy for the $(m,q,d)$ low individual degree test.
  5	
  6	\section{Non-projective Output}
  7	\label{sec:self-improvement}
  8	
  9	A large part of this chapter is devoted to proving
 10	Lemma~\ref{lem:self-improvement-helper}, which is a slightly weaker form of the
 11	projective self-improvement theorem proved in Section~\ref{sec:self-improvement-projective}.
 12	The key difference is that the output family~$H$ is only required to be a
 13	submeasurement, rather than a projective submeasurement. Once this non-projective
 14	statement is available, Theorem~\ref{thm:orthonormalization} upgrades~$H$ to a
 15	projective family without losing control of the four quantitative conclusions.
 16	
 17	Compared with the projective theorem, the helper lemma records strong
 18	self-consistency using the explicit inequality from
 19	Definition~\ref{def:strong-self-consistency}, keeps the boundedness conclusion in
 20	terms of an auxiliary operator~$Z$, and produces a much smaller error parameter.
 21	
 22	\begin{lemma}[Self-improvement with non-projective output]\label{lem:self-improvement-helper}
 23	  \lean{MIPStarRE.LDT.SelfImprovement.selfImprovementHelper}
 24	  \lean{MIPStarRE.LDT.SelfImprovement.self_improvement_helper_with_slackness_of_sdp_statement_with_slackness}
 25	  \leanok
 26	  \uses{def:polymeasurements, def:simeq, def:strong-self-consistency}
 27	  Let $G \in \polymeas{m}{q}{d}$ be a measurement with the following property:
 28	  \begin{enumerate}
 29	    \item (Consistency with~$A$): \label{item:self-improvement-G-consistency} On average over $u \sim \F_q^{m}$,
 30	    \[
 31	      A^{u}_a \ot I \simeq_{\nu} I \ot G_{[g(u)=a]}.
 32	    \]
 33	  \end{enumerate}
 34	  Let
 35	  \[
 36	    \zeta = 100m\cdot \Big(\eps^{1/2} + \delta^{1/2} + (d/q)^{1/2}\Big).
 37	  \]
 38	  Then there exists $H \in \polysub{m}{q}{d}$ with the following properties:
 39	  \begin{enumerate}
 40	    \item (Completeness): \label{item:self-improvement-completeness} If $H = \sum_h H_h$, then
 41	    \[
 42	      \bra{\psi} H \ot I \ket{\psi} \geq (1-\nu)-\zeta.
 43	    \]
 44	    \item (Consistency with~$A$): \label{item:self-improvement-A-consistency} On average over $u \sim \F_q^m$,
 45	    \[
 46	      A^u_a \ot I \simeq_{\zeta} I \ot H_{[h(u) = a]}.
 47	    \]
 48	    \item (Strong self-consistency): \label{item:self-improvement-self}
 49	    \[
 50	      \sum_{h} \bra{\psi} H_h \ot H_h \ket{\psi} \geq \bra{\psi} H \ot I \ket{\psi} - \zeta.
 51	    \]
 52	    \item (Boundedness): \label{item:self-improvement-boundedness} There exists a positive-semidefinite matrix~$Z$ such that
 53	    \[
 54	      \bra{\psi} Z \ot I \ket{\psi} -\E_{u} \sum_a \bra{\psi}  A^{u}_{a} \ot H_{[h(u)=a]} \ket{\psi} \leq \zeta
 55	    \]
 56	    and for each $h \in \polyfunc{m}{q}{d}$,
 57	    \[
 58	      Z \geq \left(\E_{u} A^{u}_{h(u)}\right).
 59	    \]
 60	  \end{enumerate}
 61	\end{lemma}
 62	\begin{proof}
 63	  \uses{lem:sdp, lem:add-in-u, lem:global-variance-of-points, prop:simeq-to-approx, prop:simeq-for-measurements}
 64	  \leanok
 65	  Let $T=\{T_g\}$ and $Z$ be the optimal solutions to the SDPs~\eqref{eq:primal-objective} and~\eqref{eq:dual-objective} given by Lemma~\ref{lem:sdp}. Then $T$ is a measurement, and
 66	  \begin{align}
 67	    \forall g \in \polyfunc{m}{q}{d}: \qquad
 68	    Z &\geq \left(\E_{u} A^{u}_{g(u)}\right), \label{eq:Z-greater-than-A}\\
 69	    T_g \cdot Z &= T_g \cdot \left(\E_{u} A^{u}_{g(u)}\right). \label{eq:swap-Z-for-A}
 70	  \end{align}
 71	  For each $u \in \F_q^m$, define $H^u=\{H_h^u\}_{h \in \polyfunc{m}{q}{d}}$ by
 72	  \[
 73	    H_h^u := A^u_{h(u)} \cdot T_h \cdot A^u_{h(u)},
 74	  \]
 75	  and let
 76	  \[
 77	    H_h := \E_{u} H_h^u.
 78	  \]
 79	  The pointwise family $H^u$ is a submeasurement because
 80	  \[
 81	    \sum_h H_h^u
 82	    = \sum_a A_a^u \cdot \Big(\sum_{h:h(u)=a} T_h\Big)\cdot A_a^u
 83	    \le \sum_a (A_a^u)^2
 84	    = I,
 85	  \]
 86	  where the inequality uses that~$T$ is a measurement and the last identity uses
 87	  that~$A$ is projective. Averaging over~$u$ gives
 88	  \[
 89	    \sum_h H_h
 90	    = \E_{u} \sum_h H_h^u
 91	    \le I,
 92	  \]
 93	  so $H$ is also a submeasurement and therefore lies in~$\polysub{m}{q}{d}$.
 94	
 95	  Set
 96	  \[
 97	    \zeta_{\mathrm{variance}} = 24m\cdot\Big(\eps + \delta + \frac{md}{q}\Big).
 98	  \]
 99	  Lemma~\ref{lem:add-in-u} below is the technical transfer from the averaged family~$H$ back to the sandwiched operators $A^u_{h(u)}T_hA^u_{h(u)}$. We use it in the completeness, consistency, strong self-consistency, and boundedness estimates that follow.
100	
101	  We now verify the four conclusions of Lemma~\ref{lem:self-improvement-helper}.
102	
103	  \emph{Proof of \ref{item:self-improvement-completeness}.}
104	  The completeness of~$H$ is
105	  \begin{align}
106	    \sum_h \bra{\psi} H_h \ot I \ket{\psi}
107	    &= \E_{u} \sum_h \bra{\psi} H^{u}_h \ot I \ket{\psi} \notag\\
108	    &= \E_{u} \sum_h \bra{\psi} \bigl(A^{u}_{h(u)} \cdot T_h \cdot A^{u}_{h(u)}\bigr) \ot I \ket{\psi}.
109	  \end{align}
110	  \lean{MIPStarRE.LDT.SelfImprovement.helper_mass_eq_avg_pointwise_sandwich_sum}
111	  Grouping the polynomials according to their value at~$u$ gives
112	  \begin{equation}\label{eq:group-by-point-value}
113	    \E_{u} \sum_h \bra{\psi} \bigl(A^{u}_{h(u)} \cdot T_h \cdot A^{u}_{h(u)}\bigr) \ot I \ket{\psi}
114	    = \E_{u} \sum_a \bra{\psi} \bigl(A^{u}_{a} \cdot T_{[h(u) = a]} \cdot A^{u}_{a}\bigr) \ot I \ket{\psi}.
115	  \end{equation}
116	  \lean{MIPStarRE.LDT.SelfImprovement.helperFiberOperator}
117	  \lean{MIPStarRE.LDT.SelfImprovement.helperFiberOperator_nonneg}
118	  \lean{MIPStarRE.LDT.SelfImprovement.helperFiberOperator_le_one}
119	  \lean{MIPStarRE.LDT.SelfImprovement.helperBracketedCompletenessQuantity}
120	  \lean{MIPStarRE.LDT.SelfImprovement.helper_pointwise_sandwich_sum_eq_bracketed}
121	  \lean{MIPStarRE.LDT.SelfImprovement.helper_mass_eq_avg_pointwise_bracketed_sum}
122	  \lean{MIPStarRE.LDT.SelfImprovement.helperBracketedCompletenessQuantity_eq_mass}
123	  We first move the leftmost copy of~$A^u_a$ across the bipartition:
124	  \begin{equation}\label{eq:first-point-projector-transport}
125	    \eqref{eq:group-by-point-value}
126	    \approx_{2\sqrt{\delta}}
127	    \E_{u} \sum_a \bra{\psi} \bigl(T_{[h(u)=a]} \cdot A^{u}_{a}\bigr) \ot A^{u}_{a} \ket{\psi}.
128	  \end{equation}
129	  The difference is bounded by Cauchy--Schwarz as
130	  in~\eqref{eq:move-first-point-projector-cauchy-schwarz}; the first factor is
131	  at most $\sqrt{2\delta}$ by self-consistency of~$A$, and the second is at
132	  most~$1$ because $T_{[h(u)=a]} \le I$.
133	  \lean{MIPStarRE.LDT.SelfImprovement.helper_first_move_second_factor_operator_le_one}
134	  \lean{MIPStarRE.LDT.SelfImprovement.helper_first_move_second_factor_le_one}
135	  \lean{MIPStarRE.LDT.SelfImprovement.helper_first_move_abs_sub_bracketed_le_two_sqrt_delta}
136	  We next remove the remaining copy of~$A^u_a$ on Bob's side:
137	  \begin{equation}\label{eq:first-moved-completeness}
138	    \eqref{eq:first-point-projector-transport}
139	    \approx_{\sqrt{\delta}}
140	    \E_{u} \sum_a \bra{\psi} \bigl(T_{[h(u)=a]} \cdot A^{u}_{a}\bigr) \ot I \ket{\psi}.
141	  \end{equation}
142	  The first Cauchy--Schwarz factor is at most~$1$ because the fiber operators form a submeasurement after grouping~$T$ by the value of~$h(u)$.
143	  \lean{MIPStarRE.LDT.SelfImprovement.helperFiberOperator_sum_eq_total}
144	  \lean{MIPStarRE.LDT.SelfImprovement.helper_second_move_first_factor_operator_le_one}
145	  \lean{MIPStarRE.LDT.SelfImprovement.helper_second_move_first_factor_le_one}
