  91	def _parse_tex_file(path: Path, root: Path) -> list[LabelLocation]:
  92	    """Return active labels in *path*, with enclosing statement/proof spans."""
  93	
  94	    lines = _active_lines(path)
  95	    stack: list[_OpenEnvironment] = []
  96	    environments: list[EnvironmentSpan] = []
  97	    labels: list[tuple[str, int]] = []
  98	
  99	    for line_no, line in enumerate(lines, 1):
 100	        for token in TOKEN_RE.finditer(line):
 101	            kind = token.group("kind")
 102	            value = token.group("value")
 103	            if kind == "begin":
 104	                stack.append(_OpenEnvironment(value, line_no))
 105	            elif kind == "label":
 106	                labels.append((value, line_no))
 107	            else:
 108	                match_at = next(
 109	                    (index for index in range(len(stack) - 1, -1, -1)
 110	                     if stack[index].name == value),
 111	                    None,
 112	                )
 113	                if match_at is None:
 114	                    continue
 115	                opened = stack[match_at]
 116	                del stack[match_at:]
 117	                environments.append(EnvironmentSpan(value, opened.start, line_no))
 118	
