/bin/bash -lc "python3 -B - <<'PY'
import pathlib, subprocess, sys, re
sys.path.insert(0,'scripts'); import blueprint_citations as b
root=pathlib.Path('.').resolve(); idx=b.build_label_index(root); base='0407cd6973dc04818d09571510a02b7cb5c25547'
files=subprocess.check_output(['git','diff','--name-only',base+'...HEAD'],text=True).splitlines()
for path in files:
 if not path.endswith('.lean'): continue
 try: text=subprocess.check_output(['git','show',f'{base}:{path}'],text=True)
 except: continue
 seen=set()
 for m in b.LEGACY_LOCATOR_RE.finditer(text):
  bs,be=b._comment_bounds(text,m.start()); key=(bs,be)
  if key in seen: continue
  seen.add(key); block=text[bs:be]; locs=list(b.LEGACY_LOCATOR_RE.finditer(block))
  vals={(x.group('path'),x.group('start'),x.group('end')) for x in locs}
  labels={x.group('label') for x in b.CODE_LABEL_RE.finditer(block) if x.group('label') in idx}
  if len(vals)>1 and len(labels)==1:
   line=text.count('\\n',0,bs)+1
   print(f'{path}:{line} labels={sorted(labels)} locators={[x.group(0) for x in locs]}')
PY"

